// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    Log logFile;

    function setUp() public {
        logFile = new Log();
        c = new X_WALLET(address(logFile));
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        vm.deal(actor, amount);
        uint256 future = block.timestamp + 1;
        vm.prank(actor);
        c.Put{value: amount}(future);
        // General rule: after any admissible Put by `actor`, the log's first
        // entry exists and its Sender is `actor`. The mutant records nothing,
        // so the entry does not exist (read reverts) for every input.
        try logFile.History(0) returns (address sender, string memory, uint256, uint256) {
            assertTrue(sender == actor);
        } catch {
            assertTrue(false);
        }
    }
}
